import { type Plan, type ScopedCase, visibleGroups, visiblePrerequisites } from "./load";
import type { Case, Platform, Prerequisite, Priority, Result, Target } from "./schema";

/**
 * Pure planning over an established set. The plugin and the validator both
 * call this; nothing else computes "runnable".
 *
 * Leaves are prerequisite ids, or `id@surface` for per-surface ones.
 */

const PRIORITY_WEIGHT: Record<Priority, number> = { smoke: 100, high: 50, normal: 20, low: 5 };

export interface Runnable {
	case: string;
	surface: string;
	title: string;
	weight: number;
	minutes: number;
}

export interface Unlock {
	leaf: string;
	summary: string;
	/** Not-yet-runnable cases that need this leaf. */
	unlocks: number;
	/** Summed weight of those cases: what establishing this leaf is worth. */
	value: number;
	/** Leaves this one requires that are not yet established. */
	blockedBy: string[];
	establish?: string;
}

export interface Blocked {
	case: string;
	surface: string;
	reason: string;
}

export interface NextStep {
	runnable: Runnable[];
	unlock: Unlock[];
	blocked: Blocked[];
}

function leaf(id: string, perSurface: boolean, surface: string): string {
	return perSurface ? `${id}@${surface}` : id;
}

/** Flattens groups and applies per-surface suffixes. Unknown ids are the validator's job. */
export function requiredLeaves(plan: Plan, sc: ScopedCase, surface: string): string[] {
	const byId = visiblePrerequisites(plan, sc.dir);
	const groups = visibleGroups(plan, sc.dir);
	const out = new Set<string>();
	const visit = (id: string) => {
		const g = groups.get(id);
		if (g) return g.members.forEach(visit);
		const p = byId.get(id);
		if (!p) return;
		out.add(leaf(id, p.per_surface, surface));
		p.requires.forEach(visit);
	};
	sc.case.requires.forEach(visit);
	return [...out];
}

function weight(plan: Plan, c: Case): number {
	return PRIORITY_WEIGHT[c.priority] + (plan.scores[c.id] ?? []).reduce((s, e) => s + e.score, 0);
}

/** Why a case can never run on this host, or null. */
function blockedReason(
	plan: Plan,
	c: Case,
	surface: string,
	platform: Platform,
	targets: readonly Target[],
): string | null {
	const s = plan.surfaces.find((x) => x.id === surface);
	if (!s) return `unknown surface ${surface}`;
	if (!s.platforms.includes(platform)) return `${surface} is not available on ${platform}`;
	if (c.platforms && !c.platforms.includes(platform)) return `case excludes ${platform}`;
	const target = targets.find((t) => t.surface === surface);
	if (c.builds && target && !c.builds.includes(target.build))
		return `case needs a ${c.builds.join("/")} build; ${surface} target is ${target.build}`;
	return null;
}

/** Every declared prerequisite by id, for reading summaries off a leaf. */
function allPrerequisites(plan: Plan): Map<string, Prerequisite> {
	const out = new Map<string, Prerequisite>();
	for (const scope of plan.scopes.values()) for (const p of scope.prerequisites) out.set(p.id, p);
	return out;
}

export function next(
	plan: Plan,
	platform: Platform,
	targets: readonly Target[],
	established: ReadonlySet<string>,
	results: readonly Result[],
	filter: { surface?: string } = {},
): NextStep {
	const done = new Set(results.map((r) => `${r.case}@${r.surface}`));
	const runnable: Runnable[] = [];
	const blocked: Blocked[] = [];
	const missing = new Map<string, Map<string, number>>(); // leaf -> gated case@surface -> weight

	for (const sc of plan.cases) {
		const c = sc.case;
		for (const surface of c.surfaces) {
			if (filter.surface && surface !== filter.surface) continue;
			const reason = blockedReason(plan, c, surface, platform, targets);
			if (reason) {
				blocked.push({ case: c.id, surface, reason });
				continue;
			}
			if (done.has(`${c.id}@${surface}`)) continue;
			const unmet = requiredLeaves(plan, sc, surface).filter((l) => !established.has(l));
			if (unmet.length === 0) {
				runnable.push({ case: c.id, surface, title: c.title, weight: weight(plan, c), minutes: c.minutes });
				continue;
			}
			for (const l of unmet) {
				const gated = missing.get(l) ?? new Map<string, number>();
				gated.set(`${c.id}@${surface}`, weight(plan, c));
				missing.set(l, gated);
			}
		}
	}
	runnable.sort((a, b) => b.weight - a.weight || a.case.localeCompare(b.case));

	const byId = allPrerequisites(plan);
	const unlock: Unlock[] = [...missing].map(([l, cases]) => {
		const [id, surface] = l.split("@");
		const p = byId.get(id)!;
		const blockedBy = p.requires
			.map((r) => leaf(r, byId.get(r)!.per_surface, surface ?? ""))
			.filter((x) => !established.has(x));
		const value = [...cases.values()].reduce((s, w) => s + w, 0);
		return { leaf: l, summary: p.summary, unlocks: cases.size, value, blockedBy, establish: p.establish };
	});
	// Most valuable first. blockedBy tells the agent how far away each one is.
	unlock.sort((a, b) => b.value - a.value || a.leaf.localeCompare(b.leaf));
	return { runnable, unlock, blocked };
}

/** Leaves to clear after recording a result for the case on `surface`. */
export function invalidatedLeaves(plan: Plan, sc: ScopedCase, surface: string): string[] {
	const byId = visiblePrerequisites(plan, sc.dir);
	return sc.case.invalidates.map((id) => leaf(id, byId.get(id)!.per_surface, surface));
}

import { resolve } from "node:path";
import { loadPlan } from "./load";
import { next } from "./plan";
import { Platform } from "./schema";

/**
 * `bun run validate [platform]`: loads everything, reports every problem,
 * and prints what a fresh host on that platform could run first.
 */
const root = resolve(import.meta.dir, "..");
const platform = Platform.parse(process.argv[2] ?? "linux");

let plan;
try {
	plan = loadPlan(root);
} catch (e) {
	console.error(String(e instanceof Error ? e.message : e));
	process.exit(1);
}

const bySurface = new Map<string, number>();
for (const { case: c } of plan.cases) for (const s of c.surfaces) bySurface.set(s, (bySurface.get(s) ?? 0) + 1);
const prereqs = [...plan.scopes.values()].reduce((n, s) => n + s.prerequisites.length, 0);
const groups = [...plan.scopes.values()].reduce((n, s) => n + s.groups.length, 0);
console.log(`${plan.cases.length} cases, ${prereqs} prerequisites, ${groups} groups in ${plan.scopes.size} scopes.`);
for (const [s, n] of [...bySurface].sort()) console.log(`  ${s}: ${n}`);

const fresh = next(plan, platform, [], new Set(), []);
console.log(`\nFresh ${platform} host: ${fresh.runnable.length} runnable, next unlocks:`);
for (const u of fresh.unlock.slice(0, 6)) console.log(`  ${u.leaf}  (+${u.unlocks})  ${u.summary}`);

import { z } from "zod";

/**
 * Checked-in contracts. Everything the agent reads or `record` writes is
 * validated against these, so a typo in a prerequisite id fails `validate`
 * instead of silently making a case unreachable.
 */

export const Platform = z.enum(["linux", "windows", "macos"]);
export type Platform = z.infer<typeof Platform>;

/** A product a case can run against. */
export const Surface = z.object({
	id: z.string().min(1),
	name: z.string().min(1),
	platforms: z.array(Platform).min(1),
	/** Cline repo path prefixes. Read by the churn producer of scores.yaml, not by the planner. */
	touches: z.array(z.string()).default([]),
});
export type Surface = z.infer<typeof Surface>;

/**
 * How the surface under test was obtained. See docs/targets.md.
 *
 * - `release`: the published artifact (marketplace, GitHub release, npm).
 *   Only releases carry production telemetry keys.
 * - `nightly`: the published nightly/beta channel artifact.
 * - `dev`: built from a git worktree at a named ref.
 */
export const Build = z.enum(["release", "nightly", "dev"]);
export type Build = z.infer<typeof Build>;

/**
 * A prerequisite is a fact about the host the agent can establish and
 * check. `per_surface: true` means the fact is tracked separately for each
 * surface (`id@surface`), e.g. "logged in" in VS Code vs. Desktop.
 *
 * Prerequisites live in `prerequisites.yaml` files beside the cases: a case
 * may reference any prerequisite defined in its own directory or an ancestor
 * directory under `cases/`.
 */
export const Prerequisite = z.object({
	id: z.string().min(1),
	summary: z.string().min(1),
	per_surface: z.boolean().default(false),
	/** Other prerequisites that must hold before this one can be established. */
	requires: z.array(z.string()).default([]),
	/** How the agent confirms the fact holds. Shell or GUI instructions. */
	check: z.string().optional(),
	/** How the agent establishes the fact. */
	establish: z.string().optional(),
	/** How the agent removes the fact, when a case needs the negative state. */
	teardown: z.string().optional(),
});
export type Prerequisite = z.infer<typeof Prerequisite>;

/** Shorthand for a bundle of prerequisites: `requires: [logged-in-ready]`. */
export const PrerequisiteGroup = z.object({
	id: z.string().min(1),
	summary: z.string().min(1),
	members: z.array(z.string()).min(1),
});
export type PrerequisiteGroup = z.infer<typeof PrerequisiteGroup>;

/** One `prerequisites.yaml`. Only the root file may declare surfaces. */
export const PrerequisitesFile = z.object({
	surfaces: z.array(Surface).optional(),
	prerequisites: z.array(Prerequisite).default([]),
	groups: z.array(PrerequisiteGroup).default([]),
});
export type PrerequisitesFile = z.infer<typeof PrerequisitesFile>;

export const Priority = z.enum(["smoke", "high", "normal", "low"]);
export type Priority = z.infer<typeof Priority>;

/**
 * One nameable thing that can be broken. The title must complete the
 * sentence "X is broken when ..." for a developer with no other context.
 */
export const Case = z.object({
	id: z.string().regex(/^[a-z0-9]+(-[a-z0-9]+)*$/, "kebab-case id"),
	title: z.string().min(1),
	priority: Priority.default("normal"),
	/** Surfaces this case applies to. */
	surfaces: z.array(z.string()).min(1),
	/** Restrict further within the surface's platforms. */
	platforms: z.array(Platform).optional(),
	/** Builds this case is valid for; omitted means any. Telemetry cases need `[release]`. */
	builds: z.array(Build).optional(),
	/** Prerequisite or group ids, resolved from this file's directory outward. */
	requires: z.array(z.string()).default([]),
	/**
	 * One-off prerequisites in prose, for authoring light. The agent
	 * establishes them at case start; they are not tracked between cases.
	 * When the same sentence recurs, promote it to a named prerequisite.
	 */
	setup: z.array(z.string()).default([]),
	/** Prerequisites the case leaves in an unknown state; cleared on record. */
	invalidates: z.array(z.string()).default([]),
	/** Cline repo path prefixes. Read by the churn producer of scores.yaml, not by the planner. */
	touches: z.array(z.string()).default([]),
	/** Related GitHub issue/PR numbers or URLs; printed with failures in summary.md. */
	refs: z.array(z.string()).default([]),
	/** Rough wall-clock budget so the planner can pack a session. */
	minutes: z.number().int().positive().default(5),
	/** Numbered steps. Lines starting with "expect" are the assertions. */
	steps: z.string().min(1),
});
export type Case = z.infer<typeof Case>;

/** A cases file holds one or more cases; group them by theme, not one per file. */
export const CasesFile = z.object({ cases: z.array(Case).min(1) });

/**
 * - pass: every expect met.
 * - pass-with-caveat: every expect met, but something worth a developer's
 *   attention happened on the way (slow, ugly, confusing, a warning).
 * - fail: an expect not met.
 * - blocked: the steps could not be attempted or completed for a reason
 *   outside the case (environment, a prerequisite silently lost, an earlier
 *   unrelated failure). Notes say what stopped it.
 *
 * Flakiness is not asserted per result; it is what a fail followed by a
 * passing retest means, and the summary reports it that way.
 */
export const Verdict = z.enum(["pass", "pass-with-caveat", "fail", "blocked"]);
export type Verdict = z.infer<typeof Verdict>;

export const Result = z.object({
	case: z.string(),
	surface: z.string(),
	verdict: Verdict,
	at: z.string().datetime(),
	/** Second attempt of a failed case, run on its own. */
	retest: z.boolean().default(false),
	/** What happened, with the facts a developer needs to reproduce or dismiss it. */
	notes: z.string().default(""),
	/** Paths returned by qbt `save_screenshot`, relative to the run directory. */
	screenshots: z.array(z.string()).default([]),
});
export type Result = z.infer<typeof Result>;

/** What is under test on this host. One target per surface. */
export const Target = z.object({
	surface: z.string(),
	build: Build,
	/** Version for release/nightly; git ref for dev. */
	version: z.string().min(1),
});
export type Target = z.infer<typeof Target>;

/** `runs/<id>/results.yaml`, appended by the plugin as the agent records. */
export const RunResults = z.object({
	platform: Platform,
	host: z.string(),
	started: z.string().datetime(),
	targets: z.array(Target).default([]),
	results: z.array(Result).default([]),
});
export type RunResults = z.infer<typeof RunResults>;

/**
 * `scores.yaml`: extra weight per case from independent producers (git churn,
 * staleness, a developer asking for a case). The crawl only reads it.
 */
export const Scores = z.record(
	z.string(),
	z.array(
		z.object({
			source: z.string().min(1),
			score: z.number(),
			reason: z.string().default(""),
		}),
	),
);
export type Scores = z.infer<typeof Scores>;

import { existsSync, readFileSync, readdirSync, statSync } from "node:fs";
import { dirname, join, relative, sep } from "node:path";
import { parse } from "yaml";
import type { z } from "zod";
import {
	type Case,
	CasesFile,
	type Prerequisite,
	type PrerequisiteGroup,
	PrerequisitesFile,
	type Scores,
	Scores as ScoresSchema,
	type Surface,
} from "./schema";

const PREREQUISITES_FILE = "prerequisites.yaml";

/** A case together with where it was declared, which fixes which prerequisites it can see. */
export interface ScopedCase {
	case: Case;
	/** Directory of the case file, relative to `cases/`; "" at the root. */
	dir: string;
}

interface Scope {
	prerequisites: Prerequisite[];
	groups: PrerequisiteGroup[];
}

export interface Plan {
	surfaces: Surface[];
	cases: ScopedCase[];
	scores: Scores;
	/** Declarations by the directory (relative to `cases/`) that holds the prerequisites.yaml. */
	scopes: Map<string, Scope>;
}

function readYaml<S extends z.ZodTypeAny>(path: string, schema: S): z.output<S> {
	const parsed = schema.safeParse(parse(readFileSync(path, "utf8")));
	if (!parsed.success) {
		const issues = parsed.error.issues.map((i) => `  ${i.path.join(".") || "(root)"}: ${i.message}`).join("\n");
		throw new Error(`${path}:\n${issues}`);
	}
	return parsed.data;
}

function walkYaml(dir: string): string[] {
	const out: string[] = [];
	for (const name of readdirSync(dir)) {
		const path = join(dir, name);
		if (statSync(path).isDirectory()) out.push(...walkYaml(path));
		else if (/\.ya?ml$/.test(name)) out.push(path);
	}
	return out.sort();
}

/** "" then each ancestor down to `dir`, so nearer declarations come last and shadow. */
function scopeChain(dir: string): string[] {
	if (dir === "") return [""];
	const parts = dir.split(sep);
	return ["", ...parts.map((_, i) => parts.slice(0, i + 1).join(sep))];
}

/** Every prerequisite a case at `dir` may reference. */
export function visiblePrerequisites(plan: Plan, dir: string): Map<string, Prerequisite> {
	const out = new Map<string, Prerequisite>();
	for (const scope of scopeChain(dir)) for (const p of plan.scopes.get(scope)?.prerequisites ?? []) out.set(p.id, p);
	return out;
}

export function visibleGroups(plan: Plan, dir: string): Map<string, PrerequisiteGroup> {
	const out = new Map<string, PrerequisiteGroup>();
	for (const scope of scopeChain(dir)) for (const g of plan.scopes.get(scope)?.groups ?? []) out.set(g.id, g);
	return out;
}

/**
 * Loads and cross-checks the whole plan. Throws with every problem found,
 * so a typo cannot silently make a case unreachable.
 */
export function loadPlan(root: string): Plan {
	const casesRoot = join(root, "cases");
	const scopes = new Map<string, Scope>();
	const cases: ScopedCase[] = [];
	let surfaces: Surface[] | undefined;

	for (const path of walkYaml(casesRoot)) {
		const dir = relative(casesRoot, dirname(path));
		if (path.endsWith(`${sep}${PREREQUISITES_FILE}`)) {
			const file = readYaml(path, PrerequisitesFile);
			if (file.surfaces) {
				if (dir !== "") throw new Error(`${path}: surfaces may only be declared in cases/${PREREQUISITES_FILE}`);
				surfaces = file.surfaces;
			}
			scopes.set(dir, { prerequisites: file.prerequisites, groups: file.groups });
		} else {
			for (const c of readYaml(path, CasesFile).cases) cases.push({ case: c, dir });
		}
	}
	if (!surfaces) throw new Error(`cases/${PREREQUISITES_FILE} must declare surfaces`);

	const scoresPath = join(root, "scores.yaml");
	const scores = existsSync(scoresPath) ? readYaml(scoresPath, ScoresSchema) : {};
	const plan: Plan = { surfaces, cases, scores, scopes };

	const problems = crossCheck(plan);
	if (problems.length) throw new Error(problems.join("\n"));
	return plan;
}

function crossCheck(plan: Plan): string[] {
	const problems: string[] = [];
	const dup = (kind: string, ids: string[]) => {
		const seen = new Set<string>();
		for (const id of ids) {
			if (seen.has(id)) problems.push(`duplicate ${kind} id: ${id}`);
			seen.add(id);
		}
	};
	dup("surface", plan.surfaces.map((s) => s.id));
	const surfaceIds = new Set(plan.surfaces.map((s) => s.id));

	for (const [dir, scope] of plan.scopes) {
		const where = dir === "" ? "cases" : `cases/${dir}`;
		dup(`prerequisite in ${where}`, scope.prerequisites.map((p) => p.id));
		dup(`group in ${where}`, scope.groups.map((g) => g.id));
		const visible = visiblePrerequisites(plan, dir);
		for (const p of scope.prerequisites)
			for (const r of p.requires)
				if (!visible.has(r)) problems.push(`${where}: prerequisite ${p.id} requires unknown ${r}`);
		for (const g of scope.groups) {
			if (visible.has(g.id)) problems.push(`${where}: group ${g.id} collides with a prerequisite`);
			for (const m of g.members) if (!visible.has(m)) problems.push(`${where}: group ${g.id} has unknown member ${m}`);
		}
	}

	dup("case", plan.cases.map((s) => s.case.id));
	const caseIds = new Set(plan.cases.map((s) => s.case.id));
	for (const { case: c, dir } of plan.cases) {
		const prereqs = visiblePrerequisites(plan, dir);
		const groups = visibleGroups(plan, dir);
		for (const s of c.surfaces) if (!surfaceIds.has(s)) problems.push(`case ${c.id} on unknown surface ${s}`);
		for (const r of c.requires)
			if (!prereqs.has(r) && !groups.has(r)) problems.push(`case ${c.id} requires unknown ${r}`);
		for (const r of c.invalidates) if (!prereqs.has(r)) problems.push(`case ${c.id} invalidates unknown ${r}`);
		if (!/^\s*(\d+[.)]|-)\s/m.test(c.steps)) problems.push(`case ${c.id} steps are not a numbered or bulleted list`);
		if (!/\bexpect\b/i.test(c.steps)) problems.push(`case ${c.id} has no "expect" assertion`);
	}
	for (const id of Object.keys(plan.scores)) if (!caseIds.has(id)) problems.push(`scores.yaml scores unknown case ${id}`);
	return problems;
}

import { appendFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { parse, stringify } from "yaml";
import type { Plan, ScopedCase } from "./load";
import { invalidatedLeaves, next, type NextStep, requiredLeaves } from "./plan";
import { type Platform, type Result, RunResults, type Target, type Verdict } from "./schema";

/**
 * One run directory, owned by whoever holds this object (the plugin). All
 * writes go through here so `runnable` can never lag a result: `record`
 * appends the result and applies `invalidates` before returning.
 *
 * On disk: run.yaml (meta + established leaves), results.yaml, journal.md.
 * Every mutation is one journal line, so `resume` rebuilds identical state.
 */

interface RunMeta {
	platform: Platform;
	host: string;
	started: string;
	targets: Target[];
	established: string[];
}

export interface RunStart {
	platform: Platform;
	host: string;
	targets: Target[];
}

/** What the agent needs to perform one case. */
export interface CaseBrief {
	case: string;
	surface: string;
	title: string;
	retest: boolean;
	setup: string[];
	steps: string;
	/** Path prefix, relative to the run directory, for qbt `save_screenshot`. Append `-<n>.png`. */
	screenshotPrefix: string;
}

export class Run {
	private constructor(
		readonly plan: Plan,
		readonly dir: string,
		readonly id: string,
		private meta: RunMeta,
		private results: Result[],
	) {}

	static create(plan: Plan, runsRoot: string, input: RunStart): Run {
		const started = new Date().toISOString();
		const id = `${started.slice(0, 19).replace(/[-:]/g, "").replace("T", "-")}-${input.platform}-${input.host}`;
		const dir = join(runsRoot, id);
		if (existsSync(dir)) throw new Error(`run ${id} already exists; pass resume`);
		for (const t of input.targets)
			if (!plan.surfaces.some((s) => s.id === t.surface)) throw new Error(`target names unknown surface ${t.surface}`);
		mkdirSync(join(dir, "screenshots"), { recursive: true });
		const meta: RunMeta = {
			platform: input.platform,
			host: input.host,
			started,
			targets: input.targets,
			established: [],
		};
		const run = new Run(plan, dir, id, meta, []);
		run.persist();
		run.journal(
			`run started on ${input.platform}/${input.host}; targets ${
				input.targets.map((t) => `${t.surface}=${t.build}:${t.version}`).join(", ") || "none declared"
			}`,
		);
		return run;
	}

	static resume(plan: Plan, runsRoot: string, id: string): Run {
		const dir = join(runsRoot, id);
		if (!existsSync(join(dir, "run.yaml"))) throw new Error(`no run at ${dir}`);
		const meta = parse(readFileSync(join(dir, "run.yaml"), "utf8")) as RunMeta;
		const results = RunResults.parse(parse(readFileSync(join(dir, "results.yaml"), "utf8"))).results;
		const run = new Run(plan, dir, id, meta, results);
		run.journal("run resumed");
		return run;
	}

	get established(): ReadonlySet<string> {
		return new Set(this.meta.established);
	}

	next(filter: { surface?: string } = {}): NextStep {
		return next(this.plan, this.meta.platform, this.meta.targets, this.established, this.results, filter);
	}

	private scopedCase(caseId: string): ScopedCase {
		const sc = this.plan.cases.find((x) => x.case.id === caseId);
		if (!sc) throw new Error(`unknown case ${caseId}`);
		return sc;
	}

	setPrerequisite(leaf: string, established: boolean, evidence?: string): void {
		const set = new Set(this.meta.established);
		if (established) set.add(leaf);
		else set.delete(leaf);
		this.meta.established = [...set].sort();
		this.persist();
		this.journal(`prereq ${leaf} = ${established}${evidence ? ` — ${evidence}` : ""}`);
	}

	/**
	 * Returns each case's one-off `setup` prose and steps; refuses unless
	 * every requested case is runnable right now. Journals the start.
	 */
	startCases(requests: { case: string; surface: string }[]): CaseBrief[] {
		if (!requests.length) throw new Error("no cases requested");
		const briefs: CaseBrief[] = [];
		for (const { case: caseId, surface } of requests) {
			const sc = this.scopedCase(caseId);
			if (!sc.case.surfaces.includes(surface)) throw new Error(`${caseId} does not run on ${surface}`);
			const prior = this.results.filter((r) => r.case === caseId && r.surface === surface);
			if (prior.length && !this.retestAllowed(prior))
				throw new Error(`${caseId}@${surface} already has a result this run`);
			const unmet = requiredLeaves(this.plan, sc, surface).filter((l) => !this.established.has(l));
			if (unmet.length) throw new Error(`${caseId}@${surface} is not runnable; unmet: ${unmet.join(", ")}`);
			briefs.push({
				case: caseId,
				surface,
				title: sc.case.title,
				retest: prior.length > 0,
				setup: sc.case.setup,
				steps: sc.case.steps,
				screenshotPrefix: join("screenshots", `${caseId}-${surface}`),
			});
		}
		for (const b of briefs) this.journal(`case ${b.case}@${b.surface} started${b.retest ? " (retest)" : ""}`);
		return briefs;
	}

	/** One second attempt is allowed after a fail. */
	private retestAllowed(prior: Result[]): boolean {
		return prior.some((r) => r.verdict === "fail") && !prior.some((r) => r.retest);
	}

	record(input: {
		case: string;
		surface: string;
		verdict: Verdict;
		notes: string;
		screenshots?: string[];
	}): NextStep {
		const sc = this.scopedCase(input.case);
		const prior = this.results.filter((r) => r.case === input.case && r.surface === input.surface);
		if (prior.length && !this.retestAllowed(prior))
			throw new Error(`${input.case}@${input.surface} already recorded this run`);
		const result: Result = {
			case: input.case,
			surface: input.surface,
			verdict: input.verdict,
			at: new Date().toISOString(),
			retest: prior.length > 0,
			notes: input.notes,
			screenshots: input.screenshots ?? [],
		};
		this.results.push(result);
		const cleared = invalidatedLeaves(this.plan, sc, input.surface);
		this.meta.established = this.meta.established.filter((l) => !cleared.includes(l));
		this.persist();
		this.journal(
			`case ${input.case}@${input.surface} ${input.verdict}${result.retest ? " (retest)" : ""}` +
				(cleared.length ? `; cleared ${cleared.join(", ")}` : "") +
				(input.notes ? `\n    ${input.notes.replace(/\n/g, "\n    ")}` : ""),
		);
		return this.next();
	}

	note(text: string): void {
		this.journal(text);
	}

	/** Failures that have not yet been retested. */
	pendingRetests(): Result[] {
		return this.results.filter((r) => {
			const prior = this.results.filter((x) => x.case === r.case && x.surface === r.surface);
			return !r.retest && this.retestAllowed(prior);
		});
	}

	/** Writes summary.md and returns its path. */
	finish(): string {
		const by: Record<string, number> = {};
		for (const r of this.results) by[r.verdict] = (by[r.verdict] ?? 0) + 1;
		const flaky = this.results.filter(
			(r) =>
				r.retest &&
				r.verdict !== "fail" &&
				this.results.some((x) => !x.retest && x.case === r.case && x.surface === r.surface && x.verdict === "fail"),
		);
		const lines = [
			`# AutoQA run ${this.id}`,
			"",
			`Platform ${this.meta.platform}, host ${this.meta.host}, started ${this.meta.started}.`,
			"",
			"## Targets",
			"",
			...(this.meta.targets.length
				? this.meta.targets.map((t) => `- ${t.surface}: ${t.build} ${t.version}`)
				: ["None declared."]),
			"",
			"## Totals",
			"",
			...Object.entries(by).map(([v, n]) => `- ${v}: ${n}`),
			"",
		];
		const section = (title: string, rows: Result[]) => {
			lines.push(`## ${title}`, "");
			if (!rows.length) lines.push("None.", "");
			for (const r of rows) {
				const c = this.scopedCase(r.case).case;
				lines.push(`### ${c.title} (${r.case}@${r.surface}${r.retest ? ", retest" : ""}) — ${r.verdict}`, "");
				if (c.refs.length) lines.push(`Refs: ${c.refs.join(", ")}`, "");
				lines.push(r.notes, "");
				for (const s of r.screenshots) lines.push(`![${s}](${s})`);
				lines.push("");
			}
		};
		const flakyKeys = new Set(flaky.map((r) => `${r.case}@${r.surface}`));
		section(
			"Failures",
			this.results.filter((r) => r.verdict === "fail" && !flakyKeys.has(`${r.case}@${r.surface}`)),
		);
		section(
			"Flaky (failed, then passed on retest)",
			this.results.filter((r) => flakyKeys.has(`${r.case}@${r.surface}`)),
		);
		section("Passed with caveats", this.results.filter((r) => r.verdict === "pass-with-caveat"));
		section("Blocked", this.results.filter((r) => r.verdict === "blocked"));
		const unmet = this.next().unlock.filter((u) => u.blockedBy.length === 0);
		lines.push("## Prerequisites never established", "");
		if (!unmet.length) lines.push("None.");
		for (const u of unmet) lines.push(`- ${u.leaf}: ${u.summary} (gates ${u.unlocks} cases)`);
		writeFileSync(join(this.dir, "summary.md"), `${lines.join("\n")}\n`);
		this.journal("run finished");
		return join(this.dir, "summary.md");
	}

	private persist(): void {
		writeFileSync(join(this.dir, "run.yaml"), stringify(this.meta));
		const out: RunResults = {
			platform: this.meta.platform,
			host: this.meta.host,
			started: this.meta.started,
			targets: this.meta.targets,
			results: this.results,
		};
		writeFileSync(join(this.dir, "results.yaml"), stringify(out));
	}

	private journal(line: string): void {
		appendFileSync(join(this.dir, "journal.md"), `- ${new Date().toISOString()} ${line}\n`);
	}
}
